/**
 * The Ladder — fixture scheduling.
 *
 * Section 3: "Fixtures are generated by the scheduler, not chosen by players."
 * Section 4.4: every fixture is two legs, with the teams swapped in leg 2, so
 * team strength cancels out completely and only skill is left.
 * Section 10: a full round-robin before any pairing repeats.
 *
 * Pure, seeded and reproducible — see `random.ts` for why.
 */

import { type Rng, createRng, shuffle } from './random'
import {
  type Pools,
  type SeasonConfig,
  availableTeams,
  scheduleShape,
  teamUsage,
} from './season'
import type { RatedTeam } from './teams'

export type LegNumber = 1 | 2
export type FixtureStatus = 'scheduled' | 'partial' | 'played'

export interface Fixture {
  id: string
  seasonId: string
  /** 1-based. A round is one fixture for every player. */
  round: number
  /** Position within the round, for stable display order. */
  order: number
  date: string | null
  playerAId: string
  playerBId: string
  /** Leg 1 teams. Leg 2 swaps them — see `teamsForLeg`. */
  teamAId: string
  teamBId: string
  status: FixtureStatus
}

/** A pairing of two players, however they happen to be ordered. */
export interface Pairing {
  playerAId: string
  playerBId: string
}

/** Stable key for a pairing, independent of which player is listed first. */
export function pairingKey(playerAId: string, playerBId: string): string {
  return [playerAId, playerBId].sort().join('::')
}

/**
 * Who fields what in a given leg. Section 4.4.
 *
 * The players keep their slots; only the teams move. This is the single place
 * the swap rule is encoded, so match entry can validate against it rather than
 * reimplementing it.
 */
export function teamsForLeg(
  fixture: Fixture,
  leg: LegNumber,
): { playerAId: string; playerBId: string; teamAId: string; teamBId: string } {
  const swapped = leg === 2

  return {
    playerAId: fixture.playerAId,
    playerBId: fixture.playerBId,
    teamAId: swapped ? fixture.teamBId : fixture.teamAId,
    teamBId: swapped ? fixture.teamAId : fixture.teamBId,
  }
}

/**
 * Which player's pool a team came from, regardless of who is fielding it in
 * this leg. Usage is always charged to the owner — see PLAN.md open question 1.
 *
 * Answers from the *drawn* teams, so it returns null for a team that was
 * swapped in at entry time under section 5.1 field 4. Pools are disjoint, so
 * where that matters, look the team up in the pools instead.
 */
export function poolOwnerOf(fixture: Fixture, teamId: string): string | null {
  if (teamId === fixture.teamAId) return fixture.playerAId
  if (teamId === fixture.teamBId) return fixture.playerBId
  return null
}

// -- Round-robin ---------------------------------------------------------------

const BYE = '__bye__'

/**
 * One full round-robin cycle: every pairing exactly once, grouped into rounds
 * in which every player appears at most once.
 *
 * Standard circle method. Four players give three rounds of two fixtures,
 * covering all six pairings — which is exactly the pattern on screen 10, where
 * rounds 8, 9 and 10 cycle through the three possible pairs of fixtures.
 *
 * An odd number of players gets a bye each round.
 */
export function roundRobinCycle(playerIds: readonly string[]): Pairing[][] {
  if (playerIds.length < 2) return []

  const entrants = playerIds.length % 2 === 0 ? [...playerIds] : [...playerIds, BYE]
  const size = entrants.length
  const rounds: Pairing[][] = []

  let wheel = entrants

  for (let round = 0; round < size - 1; round++) {
    const pairings: Pairing[] = []

    for (let i = 0; i < size / 2; i++) {
      const a = wheel[i]!
      const b = wheel[size - 1 - i]!
      if (a !== BYE && b !== BYE) pairings.push({ playerAId: a, playerBId: b })
    }

    rounds.push(pairings)
    wheel = [wheel[0]!, wheel[size - 1]!, ...wheel.slice(1, size - 1)]
  }

  return rounds
}

// -- Generation ----------------------------------------------------------------

export interface GenerateOptions {
  pools: Pools
  /** Same seed, same fixture list. "Re-draw teams" means a new seed. */
  seed: number
  /** How many rounds to add. Defaults to the rest of the season. */
  rounds?: number
  /** Fixtures already scheduled, so generation continues rather than restarts. */
  existing?: readonly Fixture[]
  /**
   * Team usage from the match log. Pass this mid-season: field 4 lets a player
   * field a different team from the one drawn, so the schedule alone is not a
   * reliable record of what has actually been used.
   */
  usage?: Readonly<Record<string, number>>
  /** Optional date per round, for the session calendar. */
  dateForRound?: (round: number) => string | null
}

export interface GenerateResult {
  /** Newly generated fixtures only, in round then order. */
  fixtures: Fixture[]
  /** Anything that stopped generation being clean. Empty means all good. */
  issues: string[]
}

/**
 * Draws fixtures.
 *
 * Rounds are grouped into round-robin cycles, and the cycle's rounds are
 * shuffled within it. That keeps the order unpredictable while guaranteeing
 * section 10's rule: every pairing meets before any pairing repeats.
 *
 * Teams are drawn from each player's own pool, least-used first so the season
 * cap is respected and usage stays level. Which player is listed first in a
 * pairing alternates between that pairing's fixtures, so the Player A slot
 * splits evenly over the season.
 */
export function generateFixtures(
  config: SeasonConfig,
  options: GenerateOptions,
): GenerateResult {
  const { pools, seed, existing = [], dateForRound } = options

  const shape = scheduleShape(config)
  const cycle = roundRobinCycle(config.playerIds)
  const issues: string[] = []

  if (cycle.length === 0) {
    return { fixtures: [], issues: ['A ladder needs at least two players.'] }
  }

  const perRound = cycle[0]!.length
  const totalRounds = shape.totalFixtures / perRound

  if (!Number.isInteger(shape.fixturesPerPairing) || !Number.isInteger(totalRounds)) {
    return {
      fixtures: [],
      issues: [
        `A season of ${config.gamesPerPairing} games per pairing over ` +
          `${config.legsPerFixture} legs does not divide into whole rounds. ` +
          'Adjust gamesPerPairing or legsPerFixture.',
      ],
    }
  }

  // A round is only "already scheduled" when all of its fixtures exist.
  // Resuming from a partial round would silently leave gaps that can never be
  // filled, so refuse rather than guess.
  const perRoundCounts = new Map<number, number>()
  for (const fixture of existing) {
    perRoundCounts.set(fixture.round, (perRoundCounts.get(fixture.round) ?? 0) + 1)
  }

  const incomplete = [...perRoundCounts.entries()]
    .filter(([, count]) => count !== perRound)
    .map(([round]) => round)
    .sort((a, b) => a - b)

  if (incomplete.length > 0) {
    return {
      fixtures: [],
      issues: [
        `Round${incomplete.length > 1 ? 's' : ''} ${incomplete.join(', ')} ` +
          `${incomplete.length > 1 ? 'are' : 'is'} incomplete, so the season ` +
          'cannot be continued from here.',
      ],
    }
  }

  const roundsAlready = perRoundCounts.size
  const remaining = Math.max(0, totalRounds - roundsAlready)
  const wanted = options.rounds ?? remaining

  if (wanted > remaining) {
    issues.push(
      `Only ${remaining} rounds remain in the season; ${wanted} were requested.`,
    )
  }

  const usage: Record<string, number> = {
    ...(options.usage ??
      teamUsage(
        existing.flatMap((fixture) => [
          { fixtureId: fixture.id, teamId: fixture.teamAId },
          { fixtureId: fixture.id, teamId: fixture.teamBId },
        ]),
      )),
  }

  const pairingCounts = new Map<string, number>()
  for (const fixture of existing) {
    const key = pairingKey(fixture.playerAId, fixture.playerBId)
    pairingCounts.set(key, (pairingCounts.get(key) ?? 0) + 1)
  }

  const fixtures: Fixture[] = []
  const toDraw = Math.min(wanted, remaining)
  let failed = false

  for (let i = 0; i < toDraw; i++) {
    const round = roundsAlready + i + 1
    const cycleIndex = Math.floor((round - 1) / cycle.length)
    const positionInCycle = (round - 1) % cycle.length

    // Reshuffling per cycle with a derived seed keeps the draw reproducible
    // while making each cycle's running order different from the last.
    const order = shuffle(cycle, createRng(seed + cycleIndex))
    const pairings = order[positionInCycle]!
    const rng = createRng(seed + round * 7919)

    pairings.forEach((pairing, index) => {
      const key = pairingKey(pairing.playerAId, pairing.playerBId)
      const met = pairingCounts.get(key) ?? 0
      pairingCounts.set(key, met + 1)

      // Alternate the Player A slot between successive meetings.
      const [playerAId, playerBId] =
        met % 2 === 0
          ? [pairing.playerAId, pairing.playerBId]
          : [pairing.playerBId, pairing.playerAId]

      const teamAId = drawTeam(playerAId, pools, usage, config, rng, issues)
      const teamBId = drawTeam(playerBId, pools, usage, config, rng, issues)

      // A fixture without teams is not a fixture. If the draw fails, the whole
      // generation fails — emitting a half-built schedule would let a caller
      // that ignored `issues` persist empty team ids as if they were real.
      if (!teamAId || !teamBId) {
        failed = true
        return
      }

      usage[teamAId] = (usage[teamAId] ?? 0) + 1
      usage[teamBId] = (usage[teamBId] ?? 0) + 1

      fixtures.push({
        id: `${config.id}-r${round}-${index + 1}`,
        seasonId: config.id,
        round,
        order: index + 1,
        date: dateForRound?.(round) ?? null,
        playerAId,
        playerBId,
        teamAId,
        teamBId,
        status: 'scheduled',
      })
    })

    if (failed) break
  }

  return {
    fixtures: failed ? [] : fixtures,
    issues: [...new Set(issues)],
  }
}

/** Least-used team from a player's pool, ties broken by the seeded draw. */
function drawTeam(
  playerId: string,
  pools: Pools,
  usage: Readonly<Record<string, number>>,
  config: SeasonConfig,
  rng: Rng,
  issues: string[],
): string | null {
  const pool = pools[playerId]

  if (!pool || pool.length === 0) {
    issues.push(`${playerId} has no team pool, so fixtures cannot be drawn.`)
    return null
  }

  const available = availableTeams(pool, usage, config)

  if (available.length === 0) {
    issues.push(
      `${playerId} has no teams left under the ${config.maxUsesPerTeam}-use cap.`,
    )
    return null
  }

  const fewest = Math.min(...available.map((team) => usage[team.id] ?? 0))
  const leastUsed = available.filter((team) => (usage[team.id] ?? 0) === fewest)

  return shuffle(leastUsed, rng)[0]!.id
}

// -- Progress ------------------------------------------------------------------

/** One logged leg, as far as the schedule is concerned. */
export interface LoggedLeg {
  fixtureId: string
  leg: LegNumber
}

/** A fixture is played only when both legs are in the log. */
export function fixtureStatus(
  fixtureId: string,
  logged: readonly LoggedLeg[],
): FixtureStatus {
  const legs = new Set(
    logged.filter((entry) => entry.fixtureId === fixtureId).map((entry) => entry.leg),
  )

  if (legs.size === 0) return 'scheduled'
  return legs.has(1) && legs.has(2) ? 'played' : 'partial'
}

export function withStatuses(
  fixtures: readonly Fixture[],
  logged: readonly LoggedLeg[],
): Fixture[] {
  return fixtures.map((fixture) => ({
    ...fixture,
    status: fixtureStatus(fixture.id, logged),
  }))
}

export interface PairingCoverage extends Pairing {
  key: string
  scheduled: number
  played: number
  /** Fixtures this pairing needs over the season. Section 10. */
  target: number
}

/** The pairing-coverage panel from screen 10. */
export function pairingCoverage(
  fixtures: readonly Fixture[],
  logged: readonly LoggedLeg[],
  config: SeasonConfig,
): PairingCoverage[] {
  const { fixturesPerPairing } = scheduleShape(config)
  const coverage = new Map<string, PairingCoverage>()

  for (let i = 0; i < config.playerIds.length; i++) {
    for (let j = i + 1; j < config.playerIds.length; j++) {
      const playerAId = config.playerIds[i]!
      const playerBId = config.playerIds[j]!
      const key = pairingKey(playerAId, playerBId)

      coverage.set(key, {
        key,
        playerAId,
        playerBId,
        scheduled: 0,
        played: 0,
        target: fixturesPerPairing,
      })
    }
  }

  for (const fixture of fixtures) {
    const entry = coverage.get(pairingKey(fixture.playerAId, fixture.playerBId))
    if (!entry) continue

    entry.scheduled++
    if (fixtureStatus(fixture.id, logged) === 'played') entry.played++
  }

  return [...coverage.values()]
}

export interface ScheduleProgress {
  fixturesScheduled: number
  fixturesPlayed: number
  totalFixtures: number
  matchesLogged: number
  totalMatches: number
  /** Highest usage across all teams, for the "most-used team" readout. */
  mostUsedTeam: { teamId: string; uses: number } | null
}

/**
 * The scheduler panel from screen 10.
 *
 * `actualUsage` should be passed once results exist. Field 4 lets a player
 * field a different team from the one drawn, so counting the schedule alone
 * would disagree with the usage table on screen 08.
 */
export function scheduleProgress(
  fixtures: readonly Fixture[],
  logged: readonly LoggedLeg[],
  config: SeasonConfig,
  actualUsage?: Readonly<Record<string, number>>,
): ScheduleProgress {
  const shape = scheduleShape(config)

  const usage =
    actualUsage ??
    teamUsage(
      fixtures.flatMap((fixture) => [
        { fixtureId: fixture.id, teamId: fixture.teamAId },
        { fixtureId: fixture.id, teamId: fixture.teamBId },
      ]),
    )

  let mostUsedTeam: { teamId: string; uses: number } | null = null
  for (const [teamId, uses] of Object.entries(usage)) {
    if (!mostUsedTeam || uses > mostUsedTeam.uses) mostUsedTeam = { teamId, uses }
  }

  return {
    fixturesScheduled: fixtures.length,
    fixturesPlayed: fixtures.filter((f) => fixtureStatus(f.id, logged) === 'played')
      .length,
    totalFixtures: shape.totalFixtures,
    matchesLogged: logged.length,
    totalMatches: shape.totalMatches,
    mostUsedTeam,
  }
}

/** Fixtures still waiting to be played, soonest first. Feeds "Next up". */
export function upcomingFixtures(
  fixtures: readonly Fixture[],
  logged: readonly LoggedLeg[],
  limit = Number.POSITIVE_INFINITY,
): Fixture[] {
  return fixtures
    .filter((fixture) => fixtureStatus(fixture.id, logged) !== 'played')
    .sort((a, b) => (a.round === b.round ? a.order - b.order : a.round - b.round))
    .slice(0, limit)
}

/** Resolves a fixture's team ids to catalogue entries, for display. */
export function fixtureTeams(
  fixture: Fixture,
  leg: LegNumber,
  index: ReadonlyMap<string, RatedTeam>,
): { teamA: RatedTeam | undefined; teamB: RatedTeam | undefined } {
  const { teamAId, teamBId } = teamsForLeg(fixture, leg)
  return { teamA: index.get(teamAId), teamB: index.get(teamBId) }
}
